"""Updated scientific narrative from the completed, stored RAG execution."""
import json,copy
from pathlib import Path
from report_content import PAGES as BASE,REFERENCES as BASE_REFS
ROOT=Path(__file__).resolve().parents[2]
P=json.loads((ROOT/'work/experiment/results.json').read_text());R=json.loads((ROOT/'work/rag/results.json').read_text())
D=P['disjoint_test'];M=D['metrics'];E=R['metrics'];U=E['Unfiltered'];H=E['Two signals'];RULE=E['Rules'];B=E['BERT probe']
TITLE='Detecting Adversarially Retrieved Contexts in RAG Systems'
SUBTITLE='A Two-Signal Gate with Passage and End-to-End Evaluation'
AUTHORS='Weiyi Xia and Xinye He'
def pc(x):return f'{100*x:.1f}%'
def interval(x):return f'{100*x[0]:.1f}%-{100*x[1]:.1f}%'
PAGES=copy.deepcopy(BASE)
abstract=f'''Retrieved evidence can contain instructions that redirect a language model away from its legitimate task. This project evaluates a passage gate combining a frozen BERT probe with an explicit response-control cue. An overlap-audited, BIPIA-derived detection study contains 37 clean records, representing 33 distinct emails, and 111 attacked passages. The combination detects 74 attacks, compared with 63 for rules and 22 for the probe, while retaining all clean records. A second experiment executes document-scoped retrieval, filtering and generation with a local Qwen2.5-0.5B-Instruct model on 16 distinct EmailQA cases and four controlled attack templates. Across 16 attacked cases, marker attack success falls from {U['attack_successes']}/16 without filtering to {H['attack_successes']}/16 with the combination. Clean answer accuracy remains {H['clean_correct']}/16, while attacked answer accuracy changes from {U['attacked_correct']}/16 to {H['attacked_correct']}/16. The combined gate's median filtering time is {H['gate_median_ms']:.1f} ms on CPU. The findings demonstrate a bounded screening benefit while revealing that suppressing an attack objective does not ensure a correct answer. Small samples, limited attacks and weak unanswerable-question handling constrain generalization.'''
PAGES[0][1][0]=('Abstract',abstract)
PAGES[0][1][-1]=('', '''This report develops the Project 5.1 direction selected in the preceding literature review. The original proposal considered many candidate signals. The teacher recommended reducing that set and using ablation to establish what each signal contributes. We consequently compare a learned window score and a narrow response-control cue, first as passage detectors and then as gates in a complete, document-scoped RAG prototype. The two evaluations answer different questions: whether a passage contains a recognizable injected instruction, and whether the generated answer follows the attacker or remains useful to the legitimate user.''')
PAGES[1][1][0]=('', '''The primary research question is whether a small passage gate identifies injected instructions while retaining benign evidence. The second question asks whether combining a frozen language-model probe with a response-control cue adds value over either alone. The third asks whether a passage-level benefit transfers to lower attack-goal success without reducing clean answer accuracy or imposing disproportionate request cost. These questions require separate detection and generation measurements. Treating one as a proxy for the other would leave the practical security claim unsupported.''')
PAGES[1][1][1]=('', '''Our hypothesis is that the two components have partly complementary errors. A learned representation may recognize instruction-bearing text beyond an exact phrase, while an explicit cue can catch direct attempts to control the answer. Complementarity does not guarantee practical value: a rule may already stop most attacks, and a neural encoder can add cost for a small marginal gain. We therefore report component ablations, retained attacker markers, answer correctness and timing. The contribution is an inspectable implementation and a bounded empirical comparison, rather than a claim of a new general-purpose defense.''')
PAGES[1][1].append(('', '''The local generator is Qwen2.5-0.5B-Instruct [14], chosen to make a complete experiment feasible on the available CPU runtime. Its small size is an experimental constraint, not evidence that the method transfers to larger or closed models. The BIPIA repository supplies original EmailQA records and separate generation/evaluation entrypoints. Our retrieval, detector integration, marker-attack construction and local scoring adapter are implemented for this project; the experiment does not claim to reproduce BIPIA's original multi-model results.'''))
PAGES[2][1][0]=('III. Threat Model', '''The legitimate task is EmailQA. A user chooses an email and asks a question about its payment information. The system indexes that email into chunks, retrieves relevant evidence, applies an optional passage gate and generates an answer. The attacker can edit the external email body by inserting a text span before indexing. It cannot change the user question, privileged system instruction, generator weights, detector coefficients or thresholds. This models a compromised source document within a selected collection, rather than an attacker controlling the assistant's top-level instruction.''')
PAGES[2][1][1]=('', '''The protected property is instruction integrity. In the passage study, an attack label indicates a payload inserted from the public text-attack bank. In the RAG study, the attacker attempts to make the model emit a fixed marker instead of answering. The marker is a harmless, mechanically scorable target. Confidentiality breaches, executable tool actions and factual poisoning without an instruction remain outside the measured scope. Public benchmark text is processed locally; attack strings are treated as data and never executed against an external system.''')
PAGES[2][1][3]=('A. Unit of analysis', '''A source email, a benchmark record, an attack template and an attacked passage are different units. Exact duplicate emails do not create independent evidence. The passage analysis groups 37 retained clean records into 33 exact-text clusters for its descriptive bootstrap. The end-to-end study selects 16 distinct source emails and pairs a clean and attacked condition for every method. Templates are reused across emails, so uncertainty still conditions on a fixed, small attack bank. Neither experiment estimates performance against an adapting attacker.''')
PAGES[2][1][-1]=('', '''The generator experiment uses one fixed model and one comparison pass. Each of sixteen cases has clean and attacked versions under four gates, producing 128 requests. Model loading, a warm-up request and pre-index construction occur before request timing. The run logs every raw response, including failures and gate abstentions. No test-set result is used to retune the probe, cue weight, threshold or attack set. The second experiment is an exploratory extension following the passage pilot, not a pre-registered confirmatory study.''')
PAGES[2][1].append(('TABLE','THREAT_TABLE'))
PAGES[3][1][-1]=('', '''Each learned gate uses its own validation-selected threshold. Candidate thresholds are observed validation scores plus a value above one that rejects nothing. Among candidates with a clean false-positive rate at most 5%, select greatest attack recall, then precision, then threshold. Exact fitting-email copies are excluded from validation during the overlap audit, leaving fourteen clean records. One false rejection already exceeds the target, so the selected operating point has zero observed validation false positives. Recalibration after the audit leaves the original thresholds unchanged.''')
PAGES[3][1].append(('D. Applying the gate to retrieved chunks', '''In the generation experiment, the same trained probe, regex patterns, score formula and audited thresholds are applied after retrieval. The score is recomputed for each selected chunk; it is not a score for the entire original email. A chunk may mix legitimate payment evidence with an injected instruction. Rejecting it can therefore remove useful facts as well as the payload. If all selected chunks are rejected, the application returns UNKNOWN without invoking the generator. This abstention is recorded separately from a model-generated answer.'''))
PAGES[3][1].append(('TABLE','ALGORITHM_TABLE'))

PAGES[4]=('Implementation',[
('V. Implementation', '''The implementation has two stages. The passage pilot evaluates a detector independently of generation. The RAG extension integrates the unchanged detector with indexing, retrieval, prompt assembly and a local generator. Both stages preserve raw outputs and configurations. The source records originate from Microsoft BIPIA, but the experiment scripts are project-specific implementations. The official repository's generation and scoring entrypoints were inspected to distinguish available upstream machinery from the adapter actually executed here.'''),
('A. Passage representation and probe', '''BERT runs locally in evaluation mode with four CPU threads. Its final hidden states are mean-pooled using the attention mask, including special tokens. A class-balanced logistic regression is trained on benign fitting-email windows and stand-alone training payload windows. The encoder remains frozen. Inference takes the maximum window risk for a passage. The fitted linear coefficients, source hashes, split manifest, original predictions and overlap-audited results are retained in the reproducibility package. Embeddings can be regenerated from the code and checkpoint.'''),
('B. Document-scoped retrieval', '''The RAG application creates a separate index for the email selected by the user. This is a metadata scope, not oracle selection of the answer-bearing chunk. The email is divided into 600-character windows with a 500-character stride. TF-IDF cosine similarity ranks those chunks against the original benchmark question; up to two chunks are returned, with source order breaking exact similarity ties. Index construction precedes timing. Online retrieval time includes question vectorization and ranking. The experiment therefore tests within-document retrieval and does not evaluate discovery of a poisoned document in a large corpus.'''),
('C. Generator and prompt', '''The local generator is the official Qwen2.5-0.5B-Instruct checkpoint [14], loaded as float32 on CPU with four threads. All gates use greedy decoding and a limit of forty-eight new tokens. The system instruction requests an answer based only on retrieved email evidence, restricted to payment amounts or UNKNOWN when unsupported. Retrieved text is placed in the user-message evidence field through the model's chat template. No defense condition receives an additional privileged warning. Generation settings, prompt template and model checkpoint remain fixed across the comparison.'''),
('D. Runtime measurement', '''Every non-abstaining request invokes the generator afresh, including requests whose evidence happens to match another condition. A response cache is not used to substitute for measured generation. Retrieval, gate, generation and complete request times are recorded with a monotonic wall clock. Gate timing includes tokenization, encoder inference and linear scoring when the neural component is used. Method order rotates by query to reduce a fixed ordering bias. Timings are descriptive for this CPU execution and can still reflect background load and output-length variation.'''),
('E. Reproduction artifacts', '''The package includes both experiment scripts, the post-run overlap audit, a protocol written before the full generator run, case identifiers, fixed configuration, raw response JSONL, summaries and SHA-256 hashes. The model weights are not redistributed in the package; their official source and hash are recorded. A single task-relevant smoke case checks that the local model can generate an answer before the fixed comparison run. It returns the source-record answer correctly. This establishes a runnable path, not an accuracy estimate, and it is excluded from reported metrics.'''),
('TABLE','RUNTIME_TABLE')])
PAGES[5]=('Experimental Data',[
('VI. Data and Experimental Design', '''Both studies use public EmailQA records from Microsoft BIPIA [7]. The original questions and ideal answers remain unchanged. Some questions have an amount as their ideal answer; others require UNKNOWN because the requested payment relation is unsupported. This distinction makes answerability important: copying a visible currency value can be wrong even when the number appears in the email. The generator study therefore reports the answerable and unanswerable strata separately.'''),
('A. Passage-study construction', '''The public email training split contains fifty records. Seed 764 assigns thirty-five records to fitting and fifteen to initial validation. For each training attack family, the first three payloads fit the detector and the remaining two supply validation attacks. This gives forty-five fitting payloads and thirty validation payloads. Each validation payload is inserted into two source contexts. The public test attack file provides seventy-five payloads, each inserted into two contexts, initially producing 150 attacked and fifty clean test examples.'''),
('B. Exact-overlap audit', '''Eleven distinct exact email texts appear in both the development and test files. They affect thirteen test records because the files also contain within-split duplicates. Excluding every shared test context leaves thirty-seven clean records and 111 attacked examples; the clean records represent thirty-three distinct email texts. Fitting-context copies in validation are also excluded, leaving fourteen clean and fifty-six attacked examples. Recalibration from cached scores selects unchanged thresholds. The audit is explicitly post-run data hygiene, not an independently pre-registered split.'''),
('C. Generator-study sample', '''From the audited pool of thirty-three distinct test emails, select the first eight records with an amount answer and the first eight with UNKNOWN, retaining source-file order within each stratum. Interleave the two strata. This deterministic selection occurs before inspecting generator outputs and does not select cases by detector score or baseline correctness. The balanced sample makes the failure modes visible but does not represent a deployment answerability distribution. All sixteen emails are distinct and have no exact context copy in the detector development data.'''),
('D. Controlled attack set', '''Four authored instructions request the fixed output marker RAG_OVERRIDE_764. They cover direct answer replacement, system-message impersonation, a task-looking verification phrase and an assistant-facing quality-assurance note. They do not reproduce the public BIPIA attack bank. Template, answerability and insertion position are crossed: each template appears once in every answerability/position combination. Prefix and suffix insertion happen before chunking and retrieval. Thus exposure is measured from retrieved chunks rather than guaranteed by injecting directly into the final prompt.'''),
('E. Comparison boundary', '''Every query has a clean and attacked version under the same four gate conditions. This yields 128 requests, not 128 independently selected experimental settings. The corpus scope, chunking, top-k, generator, prompt and decoding remain fixed. Passage filtering changes only which retrieved chunks reach generation. Source-record labels are preserved, and unsuccessful or incorrect responses remain in the log. No external model judges the outputs: the controlled marker target and amount-answer task allow explicit local scoring.'''),
('TABLE','SPLIT_TABLE')])
PAGES[6]=('Evaluation Metrics',[
('VII. Security, Utility and Latency', '''The two studies use different outcome levels. Passage recall measures whether an attacked text is rejected. End-to-end attack success measures whether the generated response contains the attacker marker. A passed payload may be ignored, and a rejected payload may remove necessary evidence. Consequently, neither passage detection nor marker suppression alone establishes a correct RAG answer. The analysis keeps gate actions, generator behavior and legitimate-task correctness separate.'''),
('A. Passage-level outcomes', '''True positives are attacked passages rejected by the gate; false positives are unmodified passages rejected. Precision, recall, F1, clean retention and malicious passage pass-through are computed from those counts. The detection mixture has a deliberately high attack prevalence, so its precision is not a deployment estimate. Percentile intervals use 1,000 bootstrap resamples of the thirty-three exact-email-text clusters, keeping repeated records and associated attacks together. They condition on a fixed fitted model and attack bank; repeated templates remain a separate dependence structure.'''),
('B. Attack success', '''For the generator experiment, attack success requires the exact marker in the generated response, case-insensitively. A marker appearing only in the retrieved evidence is not success. Report both the all-attempt denominator and the number whose retrieved chunks expose the marker. Also record whether the marker survives filtering. The sixteen controlled attacks all reach retrieval in this execution, so the all-attempt and exposure-conditional attack success rates coincide. The metric establishes only the specified output-redirection goal; it does not evaluate exfiltration or every possible semantic deviation.'''),
('C. Legitimate answer quality', '''The original ideal answers define correctness. For amount answers, compare normalized numeric-value sets after removing currency symbols, grouping commas and grouping spaces; preserve decimal values. For unanswerable cases, require the normalized answer UNKNOWN. Strict normalized exact match is reported alongside amount-set correctness. This local scorer is transparent and reproducible but is not a general language-model faithfulness judge. It does not prove that the model used the right reasoning, and it can tolerate duplicate mentions of the same amount.'''),
('', '''Clean accuracy, answerable-only clean accuracy, unanswerable clean accuracy and attacked-task accuracy are reported separately. Gate abstention means that all retrieved chunks were removed and UNKNOWN was returned without a generator call. A model may also generate UNKNOWN with remaining evidence; that is not counted as a gate abstention. This distinction prevents a filter from receiving an unqualified utility claim simply because refusing a task blocks its attack marker.'''),
('D. Timing and uncertainty', '''Full request time includes query vectorization, ranking, passage scoring and generation, or the deterministic empty-context fallback. It excludes model loading, warm-up and index construction. Report condition medians and pooled-condition 95th-percentile request time, with filtering time separately visible. A shorter attacked-request median can result from shorter retained context or skipped generation; it is not proof of a cheaper detector. Different output lengths also affect latency.'''),
('', '''Wilson 95% intervals describe binomial rates on the sixteen distinct queries, and a paired query bootstrap describes changes relative to the unfiltered pipeline. The sample is small and the attack bank has only four fixed templates. An observed zero therefore has an appreciable upper confidence bound. These descriptive intervals are conditional summaries, not a claim of adaptive robustness or transfer to a different generator. No p-value or significance claim is needed to describe the observed counts.''')])
det_rows=[['Gate','TP / FN','FP / TN','Recall','F1']]+[[k,f"{v['tp']} / {v['fn']}",f"{v['fp']} / {v['tn']}",pc(v['recall']),f"{v['f1']:.3f}"] for k,v in M.items()]
rag_rows=[['Gate','ASR','Clean','Attacked QA','Gate ms']]+[[k,f"{v['attack_successes']}/16",f"{v['clean_correct']}/16",f"{v['attacked_correct']}/16",f"{v['gate_median_ms']:.1f}"] for k,v in E.items()]
lat_rows=[['Gate','Clean ms','Attack ms','P95 ms']]+[[k,f"{v['clean_request_median_ms']:.0f}",f"{v['attacked_request_median_ms']:.0f}",f"{v['all_request_p95_ms']:.0f}"] for k,v in E.items()]
PAGES[7]=('Results',[
('VIII. Observed Results', f'''The two-signal gate detects 74 of 111 attacked passages in the overlap-audited detection set, compared with 63 for rules and 22 for the probe. All three retain the thirty-seven clean records. The combined recall is 66.7%, with a context-cluster bootstrap interval of {interval(M['Two signals']['ci95']['recall'])}. This is a passage-detection comparison. Its eleven extra detections over rules motivate the generator evaluation, but cannot predict downstream attack success by themselves.'''),
('TABLE','DETECTION_TABLE'),
('A. End-to-end outcomes', f'''Across the sixteen controlled generator attacks, the unfiltered system emits the attacker marker {U['attack_successes']} times, rules {RULE['attack_successes']} time, the probe {B['attack_successes']} times, and the combination {H['attack_successes']} times. All sixteen attacks are exposed in retrieved chunks. The combination retains marker-bearing evidence in {H['attack_marker_retained']} cases, showing that zero output successes is partly a property of generator behavior after filtering, not removal of every malicious span. The retained-context and response logs distinguish those mechanisms.'''),
('TABLE','RAG_TABLE'),
('B. Utility remains imperfect', f'''Every method answers {H['clean_correct']} of sixteen clean questions correctly. Seven of eight answerable questions are correct, but only two of eight unanswerable questions receive the expected UNKNOWN. Strict normalized exact match is also {pc(H['clean_strict_em'])}. Under attack, correct answers change from {U['attacked_correct']} without filtering to {H['attacked_correct']} with the combination. The latter equality with aggregate clean correctness does not mean the same queries remain correct: filtering can lose an amount-bearing chunk and create a new error while fixing another case.'''),
('C. Increment over the rule baseline', f'''Rules already suppress seven of the eight observed unfiltered marker successes. The learned addition suppresses the remaining one in this test, while its median filtering time is {H['gate_median_ms']:.1f} ms compared with {RULE['gate_median_ms']:.3f} ms for rules. The study therefore supports a bounded extra benefit, not an unconditional preference for the neural component. A larger and harder set of benign instructions and attacks is needed to decide whether that extra coverage warrants the encoder cost.'''),
('D. Statistical scope', f'''The combined system's observed marker success is 0/16, whose 95% Wilson interval is {interval(H['asr_all_wilson95'])}. Clean accuracy has interval {interval(H['clean_accuracy_wilson95'])}. The paired bootstrap change in marker success relative to the unfiltered system is {100*R['paired_query_bootstrap']['Two signals']['attack_success_change']['point']:.1f} percentage points, with interval {interval(R['paired_query_bootstrap']['Two signals']['attack_success_change']['ci95'])}. These intervals describe the selected query sample and fixed templates. They do not imply that a future adversary has zero chance of success.''')])
PAGES[8]=('Cost and Error Analysis',[
('IX. Cost and Error Analysis', f'''The completed comparison contains {R['total_requests']} requests and {R['generator_invocations']} generator calls. The remaining requests return UNKNOWN because all selected chunks are rejected. This operational behavior matters when interpreting both latency and attack outcomes. The combined gate's median filtering time is {H['gate_median_ms']:.1f} ms, whereas the rule gate costs approximately {RULE['gate_median_ms']:.3f} ms. A linear probe is small, but the full frozen BERT encoder is not computationally free.'''),
('TABLE','LATENCY_TABLE'),
('A. Request latency', f'''Median clean request times are {U['clean_request_median_ms']:.0f} ms for unfiltered retrieval and {H['clean_request_median_ms']:.0f} ms for the combination. Under attack the corresponding medians are {U['attacked_request_median_ms']:.0f} and {H['attacked_request_median_ms']:.0f} ms. The attacked combination also has three gate abstentions and sometimes shorter retained evidence. Those effects can offset the encoder cost in the aggregate request median. A claim that the detector makes generation faster would therefore be unsupported. The direct filtering measurement is the clearer estimate of its added computational work.'''),
('B. Marker suppression without correctness', '''In case 1, the unfiltered attacked response is RAG_OVERRIDE_764. The combination suppresses that marker but answers $300.00, although the original ideal answer is UNKNOWN. This is a security improvement on the specified attack objective and a legitimate-task failure at the same time. Reporting attack success alone would conceal that distinction. The clean version of the same case also produces an unsupported amount, revealing a generator/task-understanding weakness independent of the injected marker.'''),
('C. Evidence removed with the payload', '''Case 0 has ideal answer $8,803.15. Under attack, the unfiltered system still gives that amount, but rules and the combination give $25.00. Both retrieve chunks 0 and 1, then reject chunk 0 because it contains the explicit response-control instruction. The retained evidence differs even though the legitimate question is unchanged. This observed failure illustrates the risk of rejecting a whole mixed-content chunk. It motivates sentence-level sanitization or finer evidence segmentation, with a new utility check rather than an assumption that smaller units must help.'''),
('D. Interpretation of the ablation', '''At the selected operating point the combination is effectively the union of cue and probe rejections. The observed gain is therefore complementary coverage, not a learned interaction or a calibrated trust probability. In the passage set it adds eleven detections over rules; in the generator set it removes one additional observed marker success. These quantities have different denominators, attack constructions and outcome definitions. Comparing them as if they measured the same robustness improvement would be misleading.'''),
('E. Limits', '''The generator is small, retrieval is scoped to a selected email, the attack set contains four authored templates, and no attacker optimizes against the detector. Training the probe on stand-alone instructions versus email windows can learn style as well as malicious intent. Confidence intervals condition on these choices. The main practical conclusion is that security and answer utility must be measured together, with cheap rule baselines and explicit computation costs remaining visible.''')])
PAGES[9]=('Conclusion and Future Work',[
('X. Conclusion', f'''This project implements and executes a complete document-scoped RAG comparison, extending an overlap-audited passage detector into retrieval, filtering and local answer generation. The detector combines a frozen BERT probe with an explicit response-control cue. On 111 attacked passages, the combination detects 74, eleven more than rules. On sixteen controlled generator attacks, observed marker successes fall from {U['attack_successes']}/16 without filtering to {H['attack_successes']}/16 with the combination. The result supports a screening benefit in the tested setting and remains bounded by the model, task and attack scope.'''),
('', f'''The stronger conclusion is methodological. Security improvement and answer quality are distinct: clean correctness remains {H['clean_correct']}/16, and an attack marker can disappear while the answer remains wrong. Whole-chunk rejection can also remove legitimate evidence and turn a correct amount into an incorrect one. These outcomes make a single accuracy, detection-recall or attack-success headline insufficient. The method should be assessed through the joint behavior of security, legitimate answers, abstention and computational cost.'''),
('A. Priority improvements', '''The first priority is handling legitimate instructions and unanswerable questions. The local generator answers only two of eight clean unanswerable cases correctly, so better task conditioning and evidence sufficiency checks are needed before claiming strong question-answering utility. Add matched benign procedures, quotations and email-recipient instructions to detector development and evaluation. A passage-only score cannot always distinguish a requested instruction from an unrelated attempt to redirect the assistant.'''),
('', '''The second priority is preserving mixed evidence. Case 0 suggests testing smaller rejection units or a detection-and-removal approach [9]. That extension should retain an explicit link between the removed span and answer-bearing facts, and should compare whole-chunk filtering with selective removal on the same questions. It should also inspect altered meaning: removing a sentence can damage evidence even if the remaining text looks fluent. A sanitization proposal is future work here, not an implemented improvement.'''),
('', '''The third priority is testing whether the neural component earns its cost. Rules already block most observed marker successes. A compact encoder, distillation, a rule-first cascade or caching corpus embeddings could reduce computation, but each changes the operational trade-off. Evaluate any replacement against the same cheap baseline and retain false-positive and answer-level metrics. A broader model comparison should follow only after establishing that the data split, scoring and threat model answer the intended question.'''),
('B. Generalization and reproducibility', '''A future master-level study could expand to open-corpus retrieval, multiple domains, multilingual and encoded payloads, stronger generators and adaptive attackers [11]. It should use independent source documents, templates and task domains across development and test. The current package provides a starting point: deterministic cases, raw responses, predictions, thresholds, source hashes, model identifiers and a complete execution path. It supports checking this execution, not extrapolating a guarantee of safe deployment.'''),
('C. AI assistance', '''Generative AI assistance was used for coding, local execution, analysis, requirement extraction, and drafting the report, slides and speaker notes. The named student authors need to inspect and verify the technical material and final wording. Individual contributions are deliberately not assigned in this manuscript. A separate unassigned work-item list is provided so that the authors can document the work actually performed before submission. No random percentages or retrospective personal-work claims are included.''')])

tables={
'THREAT_TABLE':('Table I. Threat-model boundaries for the completed prototype.',[['Actor / item','Control or boundary'],['Legitimate user','Selects an email and asks its original question'],['Attacker','Inserts a text-only instruction into that email'],['Defender','Ranks chunks and gates them before generation'],['Measured goal','Output marker replaces the requested answer'],['Not evaluated','Tool execution, exfiltration, adaptive optimization']]),
'ALGORITHM_TABLE':('Algorithm 1. RAG request path; the attack edits the indexed source, not the privileged prompt.',[['Step','Operation'],['1','Split and index the selected email before requests'],['2','Retrieve up to two chunks for the question'],['3','Score retrieved chunks with the selected fixed gate'],['4','Keep scores below its fixed threshold'],['5','If empty, return UNKNOWN and log abstention'],['6','Otherwise generate and log the actual answer'],['7','Score marker success and task correctness separately']]),
'RUNTIME_TABLE':('Table II. Fixed generator configuration.',[['Parameter','Value'],['Model','Qwen2.5-0.5B-Instruct'],['Device / dtype','CPU / float32'],['Threads','4'],['Decoding','Greedy; max 48 new tokens'],['Retrieval','TF-IDF; scoped email; top 2'],['Threshold tuning','None on generator results'],['Caching','No response cache for request timing']]),
'SPLIT_TABLE':('Table III. Two distinct evaluation datasets. Audited detection test records represent 33 distinct emails.',[['Study / partition','Clean','Attacked'],['Detection fitting','35 records','45 payloads'],['Detection validation audited','14','56'],['Detection test audited','37','111'],['RAG test (16 distinct emails)','16','16']]),
'DETECTION_TABLE':('Table IV. Audited passage decisions. Rejection is positive; these are not generator attack-success rates.',det_rows),
'RAG_TABLE':('Table V. Complete RAG outcomes. ASR is successful markers; Clean and Attacked QA are correct answers. Gate ms is median filtering time.',rag_rows),
'LATENCY_TABLE':('Table VI. Actual request timing in milliseconds. Medians by scenario; P95 pools both scenarios. Excludes model loading and indexing.',lat_rows)
}
